// If the length of the input string is less than or equal to 3, return the input string as is. Otherwise, calculate the last digit and divide it by 7, which gives the first digit.
function addDozensToEnd(str) {
  if (str.length <= 3) {
    return str;
  }

  let lastDigit = parseInt(str.charAt(str.length - 1));
  let firstDigit = Math.floor(lastDigit / 7);

  // Create the new number string by slicing the first digit and the original string length to remove the last digit
  // Append the last digit to the end of the new string
  let newNumber = firstDigit + str.slice(2, str.length - 1) + lastDigit;

  return str.length >= 7 ? newNumber.toString().slice(1, 7) : newNumber.toString().slice(2);
}

